/**
 * Demo REST spec shared by the rest-plugin tests: one operation per feature (path/query/header params, nested and
 * raw bodies, write classes, nodeOnly, toolPolicy, every pagination style, async jobs with URL and base64 downloads,
 * and a raw file upload).
 */
export const DEMO_OPERATIONS = [
  {
    name: "get_item",
    title: "Get item",
    description: "Read one item",
    path: "/items/{item_id}",
    params: {
      item_id: { in: "path", type: "string", required: true, description: "Item id" },
      fields: { in: "query", type: "array", items: { type: "string" }, description: "Fields" },
      expand: { in: "query", type: "boolean", wireName: "expand_all" },
      trace: { in: "header", type: "string", wireName: "X-Trace-Id" },
    },
  },
  {
    name: "send_message",
    title: "Send message",
    description: "Send a message",
    method: "POST",
    path: "/channels/{channel}/messages",
    write: "unsafe",
    checkHint: "list the channel's recent messages",
    params: {
      channel: { in: "path", type: "string", required: true },
      text: { in: "body", type: "string", required: true, wireName: "message.text", minLength: 1 },
      silent: { in: "body", type: "boolean", wireName: "message.options.silent", default: false },
      priority: { in: "body", type: "string", enum: ["low", "high"] },
    },
  },
  {
    name: "replace_item",
    title: "Replace item",
    description: "Replace an item with a raw JSON document",
    method: "PUT",
    path: "/items/{item_id}",
    write: "idempotent",
    bodyMode: "raw",
    params: { item_id: { in: "path", type: "string", required: true }, document: { in: "body", type: "object", required: true } },
  },
  {
    name: "delete_item",
    title: "Delete item",
    description: "Delete an item",
    method: "DELETE",
    path: "/items/{item_id}",
    write: "unsafe",
    nodeOnly: true,
    params: { item_id: { in: "path", type: "string", required: true } },
  },
  {
    name: "search_items",
    title: "Search items",
    description: "Search with a POST",
    method: "POST",
    path: "/items/search",
    write: "idempotent",
    bodyMode: "form",
    toolPolicy: "optIn:DEMO_TOOL_ALLOW_SEARCH",
    params: { q: { in: "body", type: "string", required: true } },
  },
  {
    name: "list_cursor",
    title: "List (cursor)",
    description: "Cursor-paginated list",
    path: "/items",
    params: { status: { in: "query", type: "string" } },
    response: { dataPath: "data", cursorPath: "meta.next", cursorParam: "starting_after", limitParam: "page_size", hasMorePath: "meta.has_more", maxLimit: 100, defaultLimit: 20 },
  },
  {
    name: "list_links",
    title: "List (Link header)",
    description: "Link-header list",
    path: "/repos",
    params: {},
    response: { nextLinkHeader: true, limitParam: "per_page" },
  },
  {
    name: "list_pages",
    title: "List (pages)",
    description: "Page-numbered list",
    path: "/pages",
    params: {},
    response: { dataPath: "results", pagePagination: { pageParam: "page", sizeParam: "per_page" } },
  },
  {
    name: "list_offsets",
    title: "List (offsets)",
    description: "Offset list in a POST body",
    method: "POST",
    path: "/records/query",
    write: "idempotent",
    params: {},
    response: { dataPath: "records", offsetPagination: { offsetParam: "skip", limitParam: "take", totalPath: "total" } },
  },
  {
    name: "generate_image",
    title: "Generate image",
    description: "Start an image job",
    method: "POST",
    path: "/images",
    write: "unsafe",
    params: { prompt: { in: "body", type: "string", required: true } },
    job: {
      idPath: "job.id",
      poll: { path: "/images/{id}", params: { verbose: "1" } },
      statusPath: "status",
      doneValues: ["succeeded"],
      failedValues: ["failed", "canceled"],
      errorPath: "error.message",
      resultPath: "output",
      intervalMs: 0,
      timeoutMs: 60000,
    },
    download: { saveTo: { urlPaths: ["images[].url"], envDir: "DEMO_OUTPUT_DIR" } },
  },
  {
    // No resultPath: the finished status body itself is the result (with the base64 audio in it).
    name: "render_audio",
    title: "Render audio",
    description: "Start an audio job",
    method: "POST",
    path: "/audio",
    write: "unsafe",
    params: { prompt: { in: "body", type: "string", required: true } },
    job: { idPath: "id", poll: { path: "/audio/{id}" }, statusPath: "finish_reason", doneValues: ["SUCCESS"], intervalMs: 0, timeoutMs: 60000 },
    download: { saveTo: { base64Paths: ["audio"], envDir: "DEMO_OUTPUT_DIR" } },
  },
  {
    name: "upload_blob",
    title: "Upload blob",
    description: "Upload a file as the raw body",
    method: "POST",
    path: "/blobs",
    write: "unsafe",
    checkHint: "list the folder's blobs",
    bodyMode: "file",
    fileBody: { fileDirEnv: "DEMO_UPLOAD_DIR", maxFileBytes: 4096 },
    params: { file: { in: "body", type: "string", file: true, required: true, description: "File" }, folder: { in: "query", type: "string" } },
  },
];

export const demoSpec = (overrides = {}) => ({
  name: "demo-api",
  version: "0.1.0",
  description: "Demo API",
  baseUrl: "https://api.example.com/v1",
  auth: { type: "bearer", env: "DEMO_TOKEN" },
  defaultHeaders: { "x-api-version": "2026-01" },
  errors: {
    messagePath: ["error.message", "message"],
    codePath: "error.code",
    kindByCode: { token_expired: "auth_error", quota: "rate_limited" },
    retryAfterPath: "error.retry_after",
  },
  operations: DEMO_OPERATIONS,
  ...overrides,
});
